import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { SHADOWS, Z_INDEX, DURATIONS, EASINGS, readCssVar } from '../sg-tokens';

@Component({
  selector: 'sg-elevation',
  imports: [TranslateModule],
  template: `
    <h1 class="sg-h">{{ 'sg.nav.elevation' | translate }}</h1>
    <p class="sg-desc">{{ 'sg.elevation.desc' | translate }}</p>

    <section class="sg-group">
      <h2 class="sg-group-h">Shadow / Elevation</h2>
      <div class="shadows">
        @for (t of shadows; track t.var) {
          <div class="sh-card" [style.boxShadow]="'var(' + t.var + ')'">
            <span class="chip-name">{{ t.label }}</span>
          </div>
        }
      </div>
    </section>

    <section class="sg-group">
      <h2 class="sg-group-h">Z-index</h2>
      <div class="zlist">
        @for (t of zindex; track t.var) {
          <div class="zrow">
            <span class="zname">{{ t.label }}</span>
            <span class="zval">{{ val(t.var) }}</span>
          </div>
        }
      </div>
    </section>

    <section class="sg-group">
      <h2 class="sg-group-h">{{ 'sg.elevation.motionHint' | translate }}</h2>
      <div class="motions">
        @for (e of easings; track e.var) {
          <div class="mrow">
            <div class="track">
              <span class="ball" [style.transitionTimingFunction]="'var(' + e.var + ')'" [style.transitionDuration]="dur"></span>
            </div>
            <span class="chip-name">{{ e.label }}</span>
          </div>
        }
      </div>
      <div class="durs">
        @for (d of durations; track d.var) {
          <span class="dur-chip">{{ d.label }} · {{ val(d.var) }}</span>
        }
      </div>
    </section>
  `,
  styleUrls: ['../sg-page.css'],
  styles: [`
    .shadows { display: flex; flex-wrap: wrap; gap: 24px; }
    .sh-card {
      width: 160px; height: 96px; border-radius: var(--radius-2xl);
      background: var(--bg-surface); border: 1px solid var(--border-soft);
      display: flex; align-items: flex-end; padding: 10px;
    }
    .chip-name { font-size: var(--fs-12); font-weight: 500; color: var(--text-body); }

    .zlist { display: flex; flex-direction: column; gap: 4px; max-width: 360px; }
    .zrow { display: flex; justify-content: space-between; padding: 6px 10px; border-radius: var(--radius-md); background: var(--bg-surface-subtle); }
    .zname { font-size: var(--fs-13); color: var(--text-body); }
    .zval { font-size: var(--fs-13); color: var(--text-sub); font-variant-numeric: tabular-nums; }

    .motions { display: flex; flex-direction: column; gap: 10px; max-width: 480px; }
    .mrow { display: flex; align-items: center; gap: 16px; }
    .track { flex: 1; height: 20px; background: var(--bg-surface-subtle); border-radius: var(--radius-full); position: relative; overflow: hidden; }
    .ball {
      position: absolute; top: 2px; left: 2px; width: 16px; height: 16px;
      border-radius: var(--radius-full); background: var(--primary-base);
      transition-property: left; transition-timing-function: var(--ease-out); transition-duration: 300ms;
    }
    .mrow:hover .ball { left: calc(100% - 18px); }
    .durs { margin-top: 16px; display: flex; flex-wrap: wrap; gap: 8px; }
    .dur-chip {
      font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums;
      padding: 4px 10px; border: 1px solid var(--border-sub); border-radius: var(--radius-full);
    }
  `],
})
export class SgElevation {
  protected readonly shadows = SHADOWS;
  protected readonly zindex = Z_INDEX;
  protected readonly durations = DURATIONS;
  protected readonly easings = EASINGS;
  protected readonly dur = '600ms';
  protected val(v: string): string { return readCssVar(v); }
}
